Object.assign(translations.kk,{conferencePage:'Конференция туралы →',calendarHome:'Күнтізбеге қосу (.ics)',hubOpen:'Делегаттар бөліміне өту →'});
const site=document.getElementById('site');
const welcome=document.getElementById('welcome');
const video=document.getElementById('background-video');
const pause=document.getElementById('pause-video');
const nav=document.getElementById('navigation');
const menu=document.querySelector('.menu-toggle');
const nodes=[...document.querySelectorAll('[data-t]')];
const english=Object.fromEntries(nodes.map(el=>[el.dataset.t,Array.from(el.childNodes).map(n=>n.nodeName==="BR"?"\n":n.textContent).join("")]));
const englishAlt=document.querySelector('[data-alt]').alt;
let userPaused=false;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function updatePause(){pause.replaceChildren(document.createTextNode(video.paused?'Play video ▷':'Pause video Ⅱ'));pause.setAttribute('aria-label',video.paused?'Play background video':'Pause background video')}
function syncVideo(){if(welcome.hidden||userPaused||reducedMotion.matches){video.pause();updatePause()}else{video.play().then(updatePause).catch(()=>{updatePause()})}}
video.addEventListener('play',updatePause);video.addEventListener('pause',updatePause);
pause.addEventListener('click',()=>{if(video.paused){userPaused=false;video.play().then(updatePause).catch(updatePause)}else{userPaused=true;video.pause()}});
function renderLanguage(lang,focus=false){
 const valid=['en','kk','ru'].includes(lang);
 welcome.hidden=valid;site.hidden=!valid;
 document.documentElement.lang=valid?lang:'en';
 if(valid){const dict=lang==='en'?english:translations[lang];for(const el of nodes){el.textContent=dict[el.dataset.t]??english[el.dataset.t]}
 document.querySelector('[data-alt]').alt=lang==='en'?englishAlt:dict.landscapeAlt;
 document.getElementById('change-language').textContent=(lang==='kk'?'KZ':lang.toUpperCase())+' / ◎';
 document.getElementById('change-language').setAttribute('aria-label',lang==='ru'?'Изменить язык':lang==='kk'?'Тілді өзгерту':'Change language');
 document.querySelectorAll('[data-page]').forEach(a=>{a.href='/'+lang+'/'+a.dataset.page+'.html'});
 document.title=lang==='ru'?'BKMUN — Модель ООН':lang==='kk'?'BKMUN — БҰҰ моделі':'BKMUN — Model United Nations';
 nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');
 if(focus){window.scrollTo({top:0,behavior:'instant'});document.getElementById('site-title').focus({preventScroll:true})}
 }else{document.title='BKMUN — Welcome';if(focus){window.scrollTo({top:0,behavior:'instant'});document.querySelector('[data-language="en"]').focus({preventScroll:true})}}
 syncVideo();
}
function chooseLanguage(lang){history.pushState({},'',lang?'?lang='+lang:location.pathname);renderLanguage(lang,true)}
for(const el of document.querySelectorAll('[data-language]'))el.addEventListener('click',e=>{e.preventDefault();chooseLanguage(el.dataset.language)});
document.getElementById('change-language').addEventListener('click',()=>chooseLanguage(null));
document.querySelector('.footer-language').addEventListener('click',()=>chooseLanguage(null));
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open)});
nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false')}});
window.addEventListener('popstate',()=>renderLanguage(new URLSearchParams(location.search).get('lang'),true));
reducedMotion.addEventListener('change',syncVideo);
renderLanguage(new URLSearchParams(location.search).get('lang'));



